import { Scalekit } from '@scalekit-sdk/node';

async function main() {
  const scalekit = new Scalekit(
    process.env.SCALEKIT_ENV_URL!,
    process.env.SCALEKIT_CLIENT_ID!,
    process.env.SCALEKIT_CLIENT_SECRET!
  );

  const identifier = 'zealt-user01';
  const connectionName = 'github-test';

  try {
    const tools = await scalekit.agentAccount.listTools({
      identifier,
      connectionName
    });
    console.log("Tools available:", JSON.stringify(tools, null, 2));

    const result = await scalekit.agentAccount.executeTool({
      identifier,
      connectionName,
      toolName: 'github_list_repos_for_authenticated_user',
      input: { per_page: 100 }
    });
    console.log("Result type:", typeof result);
    console.log("Result:", JSON.stringify(result, null, 2));
  } catch (error) {
    console.error("Error:", error);
  }
}

main();

